"```java
@DatabaseTest
class MensagemAdminControllerIntegrationTest extends RestAssuredMockMvcTest {

    private static final String BASE_URL = "/api/admin/mensagens/";
    private final MensagemInputITDtoFactory mensagemInputITDtoFactory = new MensagemInputITDtoFactory();
    private final BridgeFaker faker = new BridgeFaker();

    @Autowired 
    private MensagemFactory mensagemFactory;

    @Autowired 
    private DAO dao;

    @Autowired 
    private LDAPJwtFactory ldapJwtFactory;

    @Test
    @DisplayName("Deve criar mensagem ativa para todos os estudantes com dados válidos")
    void storeMensagemAtivaParaTodosExpectSuccess() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(b -> {
            b.situacaoMensagem.set(2);
            b.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
            b.instituicaoIds.set(null);
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(APPLICATION_JSON_VALUE)
                .body(mensagemInputDto)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(2);
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());
        assertThat(storedMensagem.getInstituicoes()).isNullOrEmpty();
    }

    @Test
    @DisplayName("Deve criar mensagem inativa para instituições específicas com dados válidos")
    void storeMensagemInativaParaInstituicoesExpectSuccess() {
        var instituicaoIds = List.of(
                this.faker.number().randomNumber(),
                this.faker.number().randomNumber()
        );

        var mensagemInputDto = this.mensagemInputITDtoFactory.create(b -> {
            b.situacaoMensagem.set(1);
            b.dataValidade.set(null);
            b.instituicaoIds.set(instituicaoIds);
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(APPLICATION_JSON_VALUE)
                .body(mensagemInputDto)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(1);
        assertThat(storedMensagem.getDataValidade()).isNull();
        assertThat(storedMensagem.getInstituicoes()).hasSize(2);
    }

    @Test
    @DisplayName("Deve criar mensagem ativa para até 5 instituições com dados válidos")
    void storeMensagemAtivaParaCincoInstituicoesExpectSuccess() {
        var instituicaoIds = List.of(
                this.faker.number().randomNumber(),
                this.faker.number().randomNumber(),
                this.faker.number().randomNumber(),
                this.faker.number().randomNumber(),
                this.faker.number().randomNumber()
        );

        var mensagemInputDto = this.mensagemInputITDtoFactory.create(b -> {
            b.situacaoMensagem.set(2);
            b.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
            b.instituicaoIds.set(instituicaoIds);
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(APPLICATION_JSON_VALUE)
                .body(mensagemInputDto)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(2);
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());
        assertThat(storedMensagem.getInstituicoes()).hasSize(5);
    }

    @Test
    @DisplayName("Deve criar mensagem com descrição contendo tags HTML")
    void storeMensagemComHtmlNaDescricaoExpectSuccess() {
        var descricaoHtml = "<p>Notificação <strong>importante</strong></p>";

        var mensagemInputDto = this.mensagemInputITDtoFactory.create(b -> {
            b.situacaoMensagem.set(2);
            b.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
            b.descricao.set(descricaoHtml);
            b.instituicaoIds.set(null);
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(APPLICATION_JSON_VALUE)
                .body(mensagemInputDto)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getDescricao()).isEqualTo(descricaoHtml);
    }

    @Test
    @DisplayName("Deve retornar erro quando nenhuma autorização for fornecida")
    void storeMensagemSemAutorizacaoExpectUnauthorized() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.createRandom();

        given()
                .contentType(APPLICATION_JSON_VALUE)
                .body(mensagemInputDto)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(401);
    }
}
