"```java
@DatabaseTest
class MensagemAdminControllerIntegrationTest extends RestAssuredMockMvcTest {

    private static final String BASE_URL = "/api/admin/mensagens";
    private final MensagemInputITDtoFactory mensagemInputITDtoFactory = new MensagemInputITDtoFactory();
    private final BridgeFaker faker = new BridgeFaker();

    @Autowired 
    private MensagemFactory mensagemFactory;

    @Autowired 
    private DAO dao;

    @Autowired 
    private LDAPJwtFactory ldapJwtFactory;

    @Test
    @DisplayName("Deve criar mensagem ativa com dados válidos")
    void storeMensagemAtivaExpectSuccess() {
        var instituicaoIds = List.of(
            this.faker.number().randomNumber(),
            this.faker.number().randomNumber()
        );

        var mensagemInputDto = this.mensagemInputITDtoFactory.create(b -> {
            b.situacaoMensagem.set(2);
            b.instituicaoIds.set(instituicaoIds);
            b.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(JSON)
                .body(mensagemInputDto)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(mensagemInputDto.getSituacaoMensagem());
        assertThat(storedMensagem.getInstituicaoIds()).containsExactlyElementsOf(mensagemInputDto.getInstituicaoIds());
        assertThat(storedMensagem.getDataValidade()).isEqualTo(mensagemInputDto.getDataValidade());
    }

    @Test
    @DisplayName("Deve criar mensagem inativa sem instituições nem data de validade")
    void storeMensagemInativaExpectSuccess() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(b -> {
            b.situacaoMensagem.set(1);
            b.instituicaoIds.set(Collections.emptyList());
            b.dataValidade.set(null);
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(JSON)
                .body(mensagemInputDto)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getId()).isEqualTo(storedMensagemId);
        assertThat(storedMensagem.getTitulo()).isEqualTo(mensagemInputDto.getTitulo());
        assertThat(storedMensagem.getDescricao()).isEqualTo(mensagemInputDto.getDescricao());
        assertThat(storedMensagem.getSituacaoMensagem()).isEqualTo(1);
        assertThat(storedMensagem.getInstituicaoIds()).isEmpty();
        assertThat(storedMensagem.getDataValidade()).isNull();
    }

    @Test
    @DisplayName("Deve criar mensagem para todos os estudantes sem instituições específicas")
    void storeMensagemParaTodosExpectSuccess() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.create(b -> {
            b.situacaoMensagem.set(2);
            b.instituicaoIds.set(Collections.emptyList());
            b.dataValidade.set(this.faker.date().future(1, DAYS).toInstant());
        });

        var storedMensagemId = given()
                .header(withBearerAuthorization(this.ldapJwtFactory.createAdminRole()))
                .contentType(JSON)
                .body(mensagemInputDto)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(200)
                .extract()
                .as(Long.class);

        var storedMensagem = this.dao.queryFactory()
                .selectFrom(mensagem)
                .where(mensagem.id.eq(storedMensagemId))
                .fetchOne();

        assertThat(storedMensagem).isNotNull();
        assertThat(storedMensagem.getInstituicaoIds()).isEmpty();
    }

    @Test
    @DisplayName("Deve retornar erro quando nenhuma autorização é fornecida")
    void storeMensagemWithoutAuthorizationExpectUnauthorized() {
        var mensagemInputDto = this.mensagemInputITDtoFactory.createRandom();

        given()
                .contentType(JSON)
                .body(mensagemInputDto)
                .when()
                .post(BASE_URL)
                .then()
                .statusCode(401);
    }
}
