            .formParam("situacaoMensagem", inputDto.getSituacaoMensagem())
            .formParam("instituicaoIds", String.join(",", inputDto.getInstituicaoIds().stream().map(Object::toString).toList()))
            .formParam("dataValidade", inputDto.getDataValidade().toString())
        .when()
            .put(BASE_URL + mensagemInDb.getId())
        .then()
            .statusCode(200);

        var updatedMensagem = this.dao.find(Mensagem.class, mensagemInDb.getId());

        assertThat(updatedMensagem).isNotNull();
        assertThat(updatedMensagem.getId()).isEqualTo(mensagemInDb.getId());
        assertThat(updatedMensagem.getTitulo()).isEqualTo(inputDto.getTitulo());
        assertThat(updatedMensagem.getDescricao()).isEqualTo(inputDto.getDescricao());
        assertThat(updatedMensagem.getSituacaoMensagem()).isEqualTo(inputDto.getSituacaoMensagem());
        assertThat(updatedMensagem.getInstituicaoIds()).containsExactlyInAnyOrderElementsOf(inputDto.getInstituicaoIds());
        assertThat(updatedMensagem.getDataValidade()).isEqualTo(inputDto.getDataValidade());
    }

    @Test
